import json
from pathlib import Path
root=Path('src/main/resources')
def save(path,data):
 p=root/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for item in ('soul_devourer','soul_cloak'):
 save(Path('assets/lastbreath/items')/(item+'.json'),{'model':{'type':'minecraft:model','model':'lastbreath:item/'+item}})
 save(Path('assets/lastbreath/models/item')/(item+'.json'),{'parent':'minecraft:item/'+('handheld' if item=='soul_devourer' else 'generated'),'textures':{'layer0':'lastbreath:item/'+item}})
save(Path('assets/lastbreath/equipment/soul_cloak.json'),{'layers':{'humanoid':[{'texture':'lastbreath:soul_cloak'}],'humanoid_baby':[{'texture':'lastbreath:soul_cloak'}]}})
save(Path('data/lastbreath/recipe/soul_devourer.json'),{'type':'minecraft:crafting_shaped','category':'equipment','pattern':[' R ','NSN',' O '],'key':{'R':'lastbreath:red_soul_jar','N':'minecraft:netherite_scrap','S':'lastbreath:executioner_sword','O':'minecraft:obsidian'},'result':{'id':'lastbreath:soul_devourer','count':1}})
save(Path('data/lastbreath/recipe/soul_cloak.json'),{'type':'minecraft:crafting_shaped','category':'equipment','pattern':['WGW','WBW','W W'],'key':{'W':'minecraft:black_wool','G':'minecraft:gold_ingot','B':'lastbreath:soul_jar'},'result':{'id':'lastbreath:soul_cloak','count':1}})
for tag,values in {'swords':['lastbreath:soul_devourer'],'enchantable/sword':['lastbreath:soul_devourer'],'enchantable/sharp_weapon':['lastbreath:soul_devourer'],'enchantable/weapon':['lastbreath:soul_devourer'],'enchantable/durability':['lastbreath:soul_devourer','lastbreath:soul_cloak'],'chest_armor':['lastbreath:soul_cloak'],'enchantable/armor':['lastbreath:soul_cloak'],'enchantable/chest_armor':['lastbreath:soul_cloak']}.items():
 p=Path('data/minecraft/tags/item')/(tag+'.json');old=json.loads((root/p).read_text()) if (root/p).exists() else {'replace':False,'values':[]};old['values']=list(dict.fromkeys(old['values']+values));save(p,old)
